"""The query language: find transactions without writing Python."""

import re
from fractions import Fraction

from tallybook.currency import currency as _currency
from tallybook.dates import DateError, Period, parse_date
from tallybook.errors import ParseError

_NAMES = ("payee", "narration", "tag", "date", "flag", "id", "account")
_OPS = ("<=", ">=", "!=", "<", ">", "=")
_NUMBER_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?([A-Z]{3})?\Z")
_PART_RE = re.compile(r"[A-Za-z0-9_-]+\Z")


def big_int(digits):
    """int() of an ASCII digit string of any length (no interpreter digit limit)."""
    if len(digits) <= 2000:
        return int(digits)
    half = len(digits) // 2
    low = digits[half:]
    return big_int(digits[:half]) * 10 ** len(low) + big_int(low)


def parse_number(sign, whole, frac):
    """Exact Fraction of a signed decimal number given as its parts (frac may be None)."""
    frac = frac or ""
    num = big_int(whole + frac)
    if sign == "-":
        num = -num
    return Fraction(num, 10 ** len(frac))


def compare(op, left, right):
    if op == "<":
        return left < right
    if op == "<=":
        return left <= right
    if op == ">":
        return left > right
    if op == ">=":
        return left >= right
    if op == "=":
        return left == right
    return left != right


def split_account_pattern(pattern):
    """Parts of a query-dialect account pattern, or None when it is invalid."""
    parts = pattern.split(":")
    for part in parts:
        if part not in ("*", "**") and not _PART_RE.match(part):
            return None
    return parts


def account_matches(parts, account):
    """Query dialect: pattern parts match the first parts of the account; ``**`` takes any number."""
    acc = account.split(":")
    memo = {}

    def go(pi, ai):
        if pi == len(parts):
            return True
        key = (pi, ai)
        if key in memo:
            return memo[key]
        seg = parts[pi]
        if seg == "**":
            result = any(go(pi + 1, ai + k) for k in range(len(acc) - ai + 1))
        elif ai < len(acc) and (seg == "*" or seg == acc[ai]):
            result = go(pi + 1, ai + 1)
        else:
            result = False
        memo[key] = result
        return result

    return go(0, 0)


class QueryError(ParseError):
    """A query that cannot be understood; ``position`` is 1-based."""

    def __init__(self, description, position):
        super().__init__("%s at position %d" % (description, position))
        self.position = position


# --- syntax tree: tuples ("and", a, b) ("or", a, b) ("not", a) ("term", fn) ---

def _contains(attr, needle):
    needle = needle.casefold()

    def test(tx, posting):
        return needle in getattr(tx, attr).casefold()

    return test


def _text_term(needle):
    needle = needle.casefold()

    def test(tx, posting):
        return needle in tx.payee.casefold() or needle in tx.narration.casefold()

    return test


class Query:
    """A parsed query. ``matches`` and ``matching_postings`` work on plain Transactions."""

    def __init__(self, text, node):
        self.text = text
        self._node = node
        self.is_empty = node is None

    def __repr__(self):
        return "Query(%r)" % (self.text,)

    def _eval(self, node, tx, posting):
        kind = node[0]
        if kind == "term":
            return node[1](tx, posting)
        if kind == "not":
            return not self._eval(node[1], tx, posting)
        if kind == "and":
            return self._eval(node[1], tx, posting) and self._eval(node[2], tx, posting)
        return self._eval(node[1], tx, posting) or self._eval(node[2], tx, posting)

    def matching_postings(self, tx):
        """The postings of ``tx`` for which the whole expression is true, in order."""
        if self._node is None:
            return list(tx.postings)
        return [p for p in tx.postings if self._eval(self._node, tx, p)]

    def matches(self, tx):
        if self._node is None:
            return True
        return any(self._eval(self._node, tx, p) for p in tx.postings)


class _Parser:
    def __init__(self, text, chart):
        self.s = text
        self.n = len(text)
        self.chart = chart
        self.i = 0
        self.tok = None
        self.advance()

    # -- lexer ---------------------------------------------------------------
    def _skip_space(self):
        while self.i < self.n and self.s[self.i].isspace():
            self.i += 1

    def advance(self):
        """Read the next token into self.tok = (kind, position, payload)."""
        self._skip_space()
        s, i = self.s, self.i
        if i >= self.n:
            self.tok = ("eof", self.n + 1, None)
            return
        c = s[i]
        if c == "(" or c == ")":
            self.i += 1
            self.tok = ("lp" if c == "(" else "rp", i + 1, None)
            return
        if c == '"':
            text, end = self._quoted(i)
            if text == "":
                raise QueryError("empty quotes", i + 1)
            self.i = end
            self.tok = ("term", i + 1, _text_term(text))
            return
        self._word(i)

    def _quoted(self, start):
        """Read a quoted string opening at ``start``; returns (text, index after it)."""
        s, n = self.s, self.n
        out = []
        j = start + 1
        while j < n:
            c = s[j]
            if c == "\\" and j + 1 < n and s[j + 1] in '"\\':
                out.append(s[j + 1])
                j += 2
            elif c == '"':
                j += 1
                if j < n and not s[j].isspace() and s[j] not in "()":
                    raise QueryError("unexpected text after closing quote", j + 1)
                return "".join(out), j
            else:
                out.append(c)
                j += 1
        raise QueryError("unterminated quote", start + 1)

    def _is_op_at(self, j):
        for op in _OPS:
            if self.s.startswith(op, j):
                return op
        return None

    def _word(self, start):
        s, n = self.s, self.n
        j = start
        while j < n:
            c = s[j]
            if c.isspace() or c in "()" or c == ":" or c in "<>=":
                break
            if c == "!" and s.startswith("!=", j):
                break
            j += 1
        name = s[start:j]
        lname = name.lower()
        if j < n and s[j] == ":":
            self._named(start, j, lname)
            return
        op = self._is_op_at(j) if j < n else None
        if op is None and lname in ("amount", "date"):
            k = j
            while k < n and s[k].isspace():
                k += 1
            if k > j:
                op = self._is_op_at(k) if k < n else None
                if op is not None:
                    j = k
        if op is not None:
            self._comparison(start, j, lname, op)
            return
        self.i = j
        if lname == "and":
            self.tok = ("and", start + 1, None)
        elif lname == "or":
            self.tok = ("or", start + 1, None)
        elif lname == "not":
            self.tok = ("not", start + 1, None)
        else:
            self.tok = ("term", start + 1, _text_term(name))

    def _read_value(self, j):
        """Read a quoted or bare value starting at ``j``; returns (text, end, was_quoted)."""
        s, n = self.s, self.n
        if j < n and s[j] == '"':
            text, end = self._quoted(j)
            return text, end, True
        k = j
        while k < n and not s[k].isspace() and s[k] not in "()":
            k += 1
        return s[j:k], k, False

    def _named(self, start, colon, lname):
        pos = start + 1
        if lname not in _NAMES:
            raise QueryError("unknown term name '%s'" % self.s[start:colon], pos)
        value, end, quoted = self._read_value(colon + 1)
        if value == "":
            raise QueryError("missing value for '%s'" % lname, pos)
        self.i = end
        self.tok = ("term", pos, self._named_term(lname, value, pos))

    def _named_term(self, lname, value, pos):
        if lname == "payee":
            return _contains("payee", value)
        if lname == "narration":
            return _contains("narration", value)
        if lname == "tag":
            tag = value.lower()
            return lambda tx, p: tag in tx.tags
        if lname == "date":
            try:
                period = Period.parse(value)
            except DateError:
                raise QueryError("invalid period '%s'" % value, pos)
            return lambda tx, p: period.contains(tx.date)
        if lname == "flag":
            if value not in ("*", "!"):
                raise QueryError("invalid flag '%s'" % value, pos)
            return lambda tx, p: tx.flag == value
        if lname == "id":
            if not re.match(r"[0-9]+\Z", value):
                raise QueryError("invalid id '%s'" % value, pos)
            wanted = value.lstrip("0") or "0"
            return lambda tx, p: tx.id is not None and str(tx.id) == wanted
        parts = split_account_pattern(value)
        if parts is None:
            raise QueryError("invalid account pattern '%s'" % value, pos)
        if self.chart is not None and not any(
                account_matches(parts, a.path) for a in self.chart.accounts()):
            raise QueryError("no account matches '%s'" % value, pos)
        return lambda tx, p: account_matches(parts, p.account)

    def _comparison(self, start, opstart, lname, op):
        pos = start + 1
        if lname not in ("amount", "date"):
            raise QueryError("unknown term name '%s'" % self.s[start:opstart], pos)
        j = opstart + len(op)
        while j < self.n and self.s[j].isspace():
            j += 1
        value, end, _ = self._read_value(j)
        if value == "":
            raise QueryError("missing value for '%s'" % lname, pos)
        self.i = end
        if lname == "date":
            try:
                when = parse_date(value)
            except DateError:
                raise QueryError("invalid date '%s'" % value, pos)
            self.tok = ("term", pos, lambda tx, p: compare(op, tx.date, when))
            return
        m = _NUMBER_RE.match(value)
        if not m:
            raise QueryError("invalid amount '%s'" % value, pos)
        number = parse_number(m.group(1), m.group(2), m.group(3))
        code = m.group(4)

        def test(tx, posting):
            amount = posting.amount
            if amount is None:
                return False
            if code is not None and amount.currency != code:
                return False
            value = Fraction(amount.minor, 10 ** _currency(amount.currency).exponent)
            return compare(op, value, number)

        self.tok = ("term", pos, test)

    # -- grammar -------------------------------------------------------------
    def parse(self):
        if self.tok[0] == "eof":
            return None
        node = self._or()
        if self.tok[0] == "rp":
            raise QueryError("unmatched ')'", self.tok[1])
        return node

    def _or(self):
        node = self._and()
        while self.tok[0] == "or":
            self.advance()
            node = ("or", node, self._and())
        return node

    def _and(self):
        node = self._not()
        while True:
            kind = self.tok[0]
            if kind == "and":
                self.advance()
                node = ("and", node, self._not())
            elif kind in ("term", "lp", "not"):
                node = ("and", node, self._not())
            else:
                return node

    def _not(self):
        if self.tok[0] == "not":
            self.advance()
            return ("not", self._not())
        return self._atom()

    def _atom(self):
        kind, pos, payload = self.tok
        if kind == "term":
            self.advance()
            return ("term", payload)
        if kind == "lp":
            self.advance()
            node = self._or()
            if self.tok[0] != "rp":
                raise QueryError("unclosed '('", pos)
            self.advance()
            return node
        raise QueryError("a search term was expected", pos)


def parse_query(text, chart=None):
    """Parse query text into a Query; ``chart`` makes unknown account patterns an error."""
    if isinstance(text, Query):
        return text
    if not isinstance(text, str):
        raise QueryError("query must be text", 1)
    node = _Parser(text, chart).parse()
    return Query(text, node)


def select(transactions, query):
    """The transactions matching ``query`` (a Query or query text), in the given order."""
    q = parse_query(query)
    return [tx for tx in transactions if q.matches(tx)]

