"""Rules: a small hand-written language that sorts transactions into accounts."""

import dataclasses
import re
from fractions import Fraction

from tallybook.dates import DateError, parse_date
from tallybook.errors import ParseError
from tallybook.model import Posting
from tallybook.query import compare, parse_number

ACCOUNT_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*(:[A-Z][A-Za-z0-9_-]*)*\Z")
TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*\Z")
_NUMBER_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?([A-Z]{3})?\Z")
_FIELDS = ("payee", "narration", "amount", "date")
_TEXT_OPS = ("=", "!=", "~", "!~")
_NUM_OPS = ("<", "<=", ">", ">=", "=", "!=")
_ACTIONS = ("account", "tag", "narration", "payee", "flag")


class RulesError(ParseError):
    """A bad rules file; ``line`` is the 1-based line of the first bad rule (or None)."""

    def __init__(self, message, line=None):
        if line is not None:
            message = "line %d: %s" % (line, message)
        super().__init__(message)
        self.line = line


class _Bad(Exception):
    """Internal: a mistake inside one rule line."""


def _tokenize(line):
    """Split a rule line into (kind, value) tokens: str, op or word."""
    tokens = []
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c.isspace():
            i += 1
        elif c == '"':
            out = []
            i += 1
            while True:
                if i >= n:
                    raise _Bad("unterminated string")
                c = line[i]
                if c == "\\":
                    if i + 1 >= n:
                        raise _Bad("unterminated string")
                    nxt = line[i + 1]
                    out.append('"' if nxt == '"' else "\\" + nxt)
                    i += 2
                elif c == '"':
                    i += 1
                    break
                else:
                    out.append(c)
                    i += 1
            tokens.append(("str", "".join(out)))
        elif line.startswith(("!=", "!~", "<=", ">="), i):
            tokens.append(("op", line[i:i + 2]))
            i += 2
        elif c in "<>=~":
            tokens.append(("op", c))
            i += 1
        else:
            j = i
            while j < n:
                d = line[j]
                if d.isspace() or d in '"<>=~' or line.startswith(("!=", "!~"), j):
                    break
                j += 1
            tokens.append(("word", line[i:j]))
            i = j
    return tokens


class Rule:
    """One rule: its conditions and the actions it applies. ``line`` is where it was written."""

    def __init__(self, line, conditions, account=None, tags=(), narration=None, payee=None, flag=None):
        self.line = line
        self.conditions = tuple(conditions)
        self.account = account
        self.tags = tuple(tags)
        self.narration = narration
        self.payee = payee
        self.flag = flag

    def __repr__(self):
        return "Rule(line=%d)" % self.line

    def holds(self, fields):
        """True when every condition holds for ``fields`` (see RuleSet.apply)."""
        for cond in self.conditions:
            if cond[0] == "any":
                continue
            if not self._holds_one(cond, fields):
                return False
        return True

    @staticmethod
    def _holds_one(cond, fields):
        kind = cond[0]
        if kind in ("payee", "narration"):
            _, op, value = cond
            text = fields.get(kind)
            text = "" if text is None else str(text)
            if op == "=":
                return text.casefold() == value.casefold()
            if op == "!=":
                return text.casefold() != value.casefold()
            found = value.search(text) is not None
            return found if op == "~" else not found
        if kind == "amount":
            _, op, number, code = cond
            amount = fields.get("amount")
            if amount is None or (code is not None and amount.currency != code):
                return False
            from tallybook.currency import currency
            actual = Fraction(amount.minor, 10 ** currency(amount.currency).exponent)
            return compare(op, actual, number)
        _, op, when = cond
        day = fields.get("date")
        if day is None:
            return False
        return compare(op, day, when)


class RuleSet:
    """Rules in file order; the first rule whose conditions all hold wins."""

    def __init__(self, rules=()):
        self._rules = list(rules)

    def __len__(self):
        return len(self._rules)

    def __iter__(self):
        return iter(self._rules)

    def match(self, fields):
        """The first matching Rule, or None."""
        for rule in self._rules:
            if rule.holds(fields):
                return rule
        return None

    def apply(self, fields):
        """A new dict of what the winning rule sets, or None when no rule matches."""
        rule = self.match(fields)
        if rule is None:
            return None
        result = {}
        if rule.account is not None:
            result["account"] = rule.account
        if rule.tags:
            result["tags"] = list(rule.tags)
        if rule.narration is not None:
            result["narration"] = rule.narration
        if rule.payee is not None:
            result["payee"] = rule.payee
        if rule.flag is not None:
            result["flag"] = rule.flag
        return result

    def categorize(self, tx):
        """``tx`` with the winning rule applied (the same object if none matches)."""
        first = tx.postings[0].amount if tx.postings else None
        result = self.apply({"payee": tx.payee, "narration": tx.narration,
                             "amount": first, "date": tx.date})
        if result is None:
            return tx
        changes = {"postings": list(tx.postings)}
        for key in ("payee", "narration", "flag"):
            if key in result:
                changes[key] = result[key]
        if "tags" in result:
            changes["tags"] = tuple(sorted(set(tx.tags) | set(result["tags"])))
        if "account" in result and len(tx.postings) == 2:
            second = tx.postings[1]
            changes["postings"][1] = dataclasses.replace(second, account=result["account"])
        return dataclasses.replace(tx, **changes)


def _parse_amount_value(word):
    m = _NUMBER_RE.match(word)
    if not m:
        raise _Bad("invalid amount '%s'" % word)
    return parse_number(m.group(1), m.group(2), m.group(3)), m.group(4)


def _parse_condition(tokens, pos):
    """Parse one condition at ``pos``; returns (condition, new position)."""
    if pos >= len(tokens):
        raise _Bad("condition expected")
    kind, field = tokens[pos]
    if kind != "word":
        raise _Bad("condition expected")
    if field == "any":
        return ("any",), pos + 1
    if field not in _FIELDS:
        raise _Bad("unknown field '%s'" % field)
    if pos + 2 >= len(tokens) + 0 and pos + 2 > len(tokens) - 1 and pos + 2 != len(tokens) - 1:
        raise _Bad("incomplete condition for '%s'" % field)
    if pos + 2 >= len(tokens):
        raise _Bad("incomplete condition for '%s'" % field)
    okind, op = tokens[pos + 1]
    vkind, value = tokens[pos + 2]
    if okind != "op":
        raise _Bad("operator expected after '%s'" % field)
    if field in ("payee", "narration"):
        if op not in _TEXT_OPS:
            raise _Bad("operator '%s' does not belong to %s" % (op, field))
        if vkind != "str":
            raise _Bad("quoted text expected after '%s %s'" % (field, op))
        if op in ("~", "!~"):
            try:
                value = re.compile(value, re.IGNORECASE)
            except re.error as exc:
                raise _Bad("bad regular expression: %s" % exc)
        return (field, op, value), pos + 3
    if op not in _NUM_OPS:
        raise _Bad("operator '%s' does not belong to %s" % (op, field))
    if vkind != "word":
        raise _Bad("%s value expected after '%s'" % (field, op))
    if field == "amount":
        number, code = _parse_amount_value(value)
        return ("amount", op, number, code), pos + 3
    try:
        when = parse_date(value)
    except DateError:
        raise _Bad("invalid date '%s'" % value)
    return ("date", op, when), pos + 3


def _parse_actions(tokens, pos):
    actions = {"tags": []}
    start = pos
    while pos < len(tokens):
        kind, name = tokens[pos]
        if kind != "word" or name not in _ACTIONS:
            raise _Bad("unknown action '%s'" % name)
        if pos + 1 >= len(tokens):
            raise _Bad("missing value for '%s'" % name)
        vkind, value = tokens[pos + 1]
        pos += 2
        if name in ("narration", "payee"):
            if vkind != "str":
                raise _Bad("quoted text expected for '%s'" % name)
            if name == "payee" and not value.strip():
                raise _Bad("payee must not be empty")
        elif vkind != "word":
            raise _Bad("bad value for '%s'" % name)
        elif name == "account" and not ACCOUNT_RE.match(value):
            raise _Bad("invalid account path '%s'" % value)
        elif name == "tag":
            if not TAG_RE.match(value):
                raise _Bad("invalid tag '%s'" % value)
            value = value.lower()
            if value not in actions["tags"]:
                actions["tags"].append(value)
            continue
        elif name == "flag" and value not in ("*", "!"):
            raise _Bad("invalid flag '%s'" % value)
        if name in actions:
            raise _Bad("'%s' given twice" % name)
        actions[name] = value
    if pos == start:
        raise _Bad("no action after 'then'")
    return actions


def _parse_rule(line_no, line):
    tokens = _tokenize(line)
    if not tokens or tokens[0] != ("word", "when"):
        raise _Bad("rule must start with 'when'")
    conditions = []
    pos = 1
    while True:
        cond, pos = _parse_condition(tokens, pos)
        conditions.append(cond)
        if pos >= len(tokens):
            raise _Bad("missing 'then'")
        if tokens[pos] == ("word", "then"):
            pos += 1
            break
        if tokens[pos] != ("word", "and"):
            raise _Bad("'and' or 'then' expected")
        pos += 1
    if any(c[0] == "any" for c in conditions) and len(conditions) > 1:
        raise _Bad("'any' cannot be combined with other conditions")
    actions = _parse_actions(tokens, pos)
    return Rule(line_no, conditions, account=actions.get("account"), tags=actions["tags"],
                narration=actions.get("narration"), payee=actions.get("payee"),
                flag=actions.get("flag"))


def parse_rules(text):
    """Parse a rules file into a RuleSet; a mistake raises RulesError with its line."""
    if not isinstance(text, str):
        raise RulesError("rules must be text")
    if text.startswith("﻿"):
        text = text[1:]
    rules = []
    for number, line in enumerate(re.split(r"\r\n|\n|\r", text), 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        try:
            rules.append(_parse_rule(number, line))
        except _Bad as exc:
            raise RulesError(str(exc), number)
    return RuleSet(rules)

