"""Importing a bank's CSV statement through a per-bank profile."""

import datetime
import re
from collections import Counter
from dataclasses import dataclass, field
from typing import List, Tuple

from tallybook.currency import CURRENCIES
from tallybook.errors import ParseError
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tallybook.query import big_int
from tallybook.rules import ACCOUNT_RE, RuleSet, TAG_RE, parse_rules, RulesError

_DELIMITERS = {"comma": ",", "tab": "\t", "semicolon": ";", "pipe": "|", "space": " "}
_THOUSANDS = {"none": "", "comma": ",", "dot": ".", "space": " ", "apostrophe": "'"}
_BOOLS = {"yes": True, "true": True, "no": False, "false": False}
_MONTHS = ["january", "february", "march", "april", "may", "june", "july", "august",
           "september", "october", "november", "december"]
_COLUMN_SETTINGS = ("date_column", "payee_column", "narration_column", "amount_column",
                    "debit_column", "credit_column")
_SETTINGS = _COLUMN_SETTINGS + ("currency", "account", "default_account", "date_format", "delimiter",
                                "skip_rows", "has_header", "negate", "decimal_separator",
                                "thousands_separator", "flag", "tags")
_LINE_BREAK = re.compile(r"\r\n|\n|\r")


class CsvImportError(ParseError):
    """A bad profile or unreadable statement; ``line`` is the profile line, or None."""

    def __init__(self, message, line=None):
        if line is not None:
            message = "line %d: %s" % (line, message)
        super().__init__(message)
        self.line = line


@dataclass(frozen=True)
class ImportProfile:
    date_column: str
    payee_column: str
    currency: str
    account: str
    date_format: str = "%Y-%m-%d"
    narration_column: str = None
    amount_column: str = None
    debit_column: str = None
    credit_column: str = None
    default_account: str = None
    delimiter: str = ","
    skip_rows: int = 0
    has_header: bool = True
    negate: bool = False
    decimal_separator: str = "."
    thousands_separator: str = ""
    flag: str = "*"
    tags: Tuple[str, ...] = ()


@dataclass
class ImportResult:
    transactions: List[Transaction] = field(default_factory=list)
    duplicates: List[Transaction] = field(default_factory=list)
    errors: List[Tuple[int, str]] = field(default_factory=list)


class _Bad(Exception):
    pass


# --- date formats ------------------------------------------------------------

def _compile_date_format(fmt):
    """Regex and group order for a date_format; raises _Bad when the format is unusable."""
    out, kinds = [], []
    i = 0
    while i < len(fmt):
        c = fmt[i]
        if c != "%":
            out.append(re.escape(c))
            i += 1
            continue
        d = fmt[i + 1:i + 2]
        i += 2
        if d == "%":
            out.append("%")
        elif d == "Y":
            out.append("([0-9]{4})")
            kinds.append("Y")
        elif d == "y":
            out.append("([0-9]{2})")
            kinds.append("y")
        elif d in ("m", "d"):
            out.append("([0-9]{1,2})")
            kinds.append(d)
        elif d == "b":
            out.append("((?i:%s))" % "|".join(m[:3] for m in _MONTHS))
            kinds.append("b")
        elif d == "B":
            out.append("((?i:%s))" % "|".join(_MONTHS))
            kinds.append("B")
        else:
            raise _Bad("unsupported directive '%%%s' in date_format" % d)
    years = [k for k in kinds if k in "Yy"]
    months = [k for k in kinds if k in ("m", "b", "B")]
    days = [k for k in kinds if k == "d"]
    if len(years) != 1 or len(months) != 1 or len(days) != 1:
        raise _Bad("date_format must contain a year, a month and a day, each once")
    return re.compile("".join(out) + r"\Z"), kinds


def _parse_cell_date(cell, compiled):
    regex, kinds = compiled
    m = regex.match(cell)
    if not m:
        return None
    year = month = day = None
    for kind, text in zip(kinds, m.groups()):
        if kind == "Y":
            year = int(text)
        elif kind == "y":
            year = 2000 + int(text)
        elif kind == "d":
            day = int(text)
        elif kind == "m":
            month = int(text)
        elif kind == "b":
            month = [x[:3] for x in _MONTHS].index(text.lower()) + 1
        else:
            month = _MONTHS.index(text.lower()) + 1
    try:
        return datetime.date(year, month, day)
    except ValueError:
        return None


# --- profile ----------------------------------------------------------------

def _column_value(value):
    if value == "":
        raise _Bad("empty column")
    if value.startswith("#"):
        digits = value[1:]
        if not re.match(r"[0-9]+\Z", digits) or big_int(digits) < 1:
            raise _Bad("bad column number '%s'" % value)
    return value


def _setting_value(name, value):
    if name in _COLUMN_SETTINGS:
        return _column_value(value)
    if name == "currency":
        if value not in CURRENCIES:
            raise _Bad("unknown currency '%s'" % value)
        return value
    if name in ("account", "default_account"):
        if not ACCOUNT_RE.match(value):
            raise _Bad("invalid account path '%s'" % value)
        return value
    if name == "date_format":
        _compile_date_format(value)
        return value
    if name == "delimiter":
        if value in _DELIMITERS:
            return _DELIMITERS[value]
        if len(value) == 1 and value not in '"\r\n':
            return value
        raise _Bad("bad delimiter '%s'" % value)
    if name == "skip_rows":
        if not re.match(r"[0-9]+\Z", value):
            raise _Bad("bad skip_rows '%s'" % value)
        return big_int(value)
    if name in ("has_header", "negate"):
        if value.lower() not in _BOOLS:
            raise _Bad("bad value '%s' for %s" % (value, name))
        return _BOOLS[value.lower()]
    if name == "decimal_separator":
        if value not in (".", ","):
            raise _Bad("bad decimal_separator '%s'" % value)
        return value
    if name == "thousands_separator":
        if value in _THOUSANDS:
            return _THOUSANDS[value]
        if value in (",", ".", "'", " "):
            return value
        raise _Bad("bad thousands_separator '%s'" % value)
    if name == "flag":
        if value not in ("*", "!"):
            raise _Bad("bad flag '%s'" % value)
        return value
    tags = [t.strip() for t in value.split(",")]
    if not value or any(not TAG_RE.match(t) for t in tags):
        raise _Bad("bad tags '%s'" % value)
    return tuple(sorted(set(t.lower() for t in tags)))


def parse_profile(text):
    """Parse profile text into an ImportProfile (CsvImportError on any problem)."""
    if not isinstance(text, str):
        raise CsvImportError("profile must be text")
    if text.startswith("﻿"):
        text = text[1:]
    values, lines = {}, {}
    first_error = None
    for number, raw in enumerate(_LINE_BREAK.split(text), 1):
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        try:
            if "=" not in raw:
                raise _Bad("expected 'setting = value'")
            name, _, value = raw.partition("=")
            name, value = name.strip(), value.strip()
            if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
                value = value[1:-1]
            if name not in _SETTINGS:
                raise _Bad("unknown setting '%s'" % name)
            if name in values:
                raise _Bad("setting '%s' given twice" % name)
            values[name] = _setting_value(name, value)
            lines[name] = number
        except _Bad as exc:
            first_error = (number, str(exc))
            break
    has_header = values.get("has_header", True)
    if not has_header:
        for name in _COLUMN_SETTINGS:
            if name in values and not values[name].startswith("#"):
                if first_error is None or lines[name] < first_error[0]:
                    first_error = (lines[name], "column '%s' must be written #N without a header" % values[name])
                break
    if first_error is not None:
        raise CsvImportError(first_error[1], first_error[0])
    for name in ("date_column", "payee_column", "currency", "account"):
        if name not in values:
            raise CsvImportError("missing required setting '%s'" % name)
    amount, debit, credit = (values.get(k) for k in ("amount_column", "debit_column", "credit_column"))
    if amount is not None and (debit is not None or credit is not None):
        raise CsvImportError("amount_column cannot be combined with debit_column/credit_column")
    if amount is None and (debit is None or credit is None):
        raise CsvImportError("need amount_column, or both debit_column and credit_column")
    if values.get("decimal_separator", ".") == values.get("thousands_separator", ""):
        raise CsvImportError("decimal_separator and thousands_separator must differ")
    return ImportProfile(**values)


# --- reading the file ---------------------------------------------------------

def _skip_lines(text, count):
    """Drop ``count`` lines from the top of ``text``; returns the rest."""
    pos = 0
    for _ in range(count):
        m = _LINE_BREAK.search(text, pos)
        if m is None:
            return ""
        pos = m.end()
    return text[pos:]


def _read_records(text, delimiter, first_line):
    """CSV records as (start line number, cells); handles quoted fields spanning lines."""
    records = []
    n = len(text)
    i = 0
    line = first_line
    while i < n:
        start_line = line
        cells = []
        while True:
            cell = []
            if i < n and text[i] == '"':
                i += 1
                while i < n:
                    c = text[i]
                    if c == '"':
                        if text.startswith('"', i + 1):
                            cell.append('"')
                            i += 2
                            continue
                        i += 1
                        break
                    if c == "\r":
                        if text.startswith("\n", i + 1):
                            i += 1
                        line += 1
                        cell.append("\n" if False else text[i - 0] if False else "\n")
                        i += 1
                        continue
                    if c == "\n":
                        line += 1
                    cell.append(c)
                    i += 1
            while i < n and text[i] != delimiter and text[i] not in "\r\n":
                cell.append(text[i])
                i += 1
            cells.append("".join(cell))
            if i < n and text[i] == delimiter:
                i += 1
                continue
            break
