            if text[i] == "\r" and text.startswith("\n", i + 1):
                i += 1
            i += 1
            line += 1
        records.append((start_line, cells))
    return records


# --- amounts ------------------------------------------------------------------

def _parse_money_cell(cell, profile, exponent):
    """Signed minor units of one amount cell; raises _Bad."""
    text = cell
    negative = False
    if text.startswith("(") and text.endswith(")") and len(text) >= 2:
        text = text[1:-1]
        negative = True
        if text[:1] in ("+", "-"):
            raise _Bad("invalid amount '%s'" % cell)
    elif text[:1] in ("+", "-"):
        negative = text[0] == "-"
        text = text[1:]
    dec, thou = profile.decimal_separator, profile.thousands_separator
    whole, sep, frac = text.partition(dec)
    if sep and not re.match(r"[0-9]+\Z", frac):
        raise _Bad("invalid amount '%s'" % cell)
    if thou:
        grouped = re.match(r"[0-9]{1,3}(?:%s[0-9]{3})+\Z" % re.escape(thou), whole)
        if grouped:
            whole = whole.replace(thou, "")
    if not re.match(r"[0-9]+\Z", whole):
        raise _Bad("invalid amount '%s'" % cell)
    if len(frac) > exponent:
        raise _Bad("amount '%s' has more than %d decimal places" % (cell, exponent))
    minor = big_int(whole + frac.ljust(exponent, "0"))
    return -minor if negative else minor


class _Columns:
    """Resolves the profile's column names/numbers to cell indexes."""

    def __init__(self, profile, header):
