            payee = result.get("payee", payee)
            narration = result.get("narration", narration)
            flag = result.get("flag", flag)
            tags.update(result.get("tags", ()))
    if counter is None:
        raise _Bad("no account for this row: no rule matched and no default_account is set")
    postings = [Posting(profile.account, amount), Posting(counter, -amount)]
    return Transaction(when, payee, narration, postings, tuple(sorted(tags)), flag, None)


